import{_ as i,l,o as a,c as s,v as t,p as E,x as r,d,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"晶圆边缘曝光","description":"","frontmatter":{"title":"晶圆边缘曝光","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/wafer-edge-exposure.md","filePath":"litho/wafer-edge-exposure.md","lastUpdated":1789023840000}'),p={name:"litho/wafer-edge-exposure.md"};function c(_,e,B,u,f,m){const o=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="晶圆边缘曝光" tabindex="-1">晶圆边缘曝光 <a class="header-anchor" href="#晶圆边缘曝光" aria-label="Permalink to &quot;晶圆边缘曝光&quot;">​</a></h1><div class="epigraph"><p>WEE 用独立光源把边缘胶曝光掉，避免边缘残胶进刻蚀腔。它不是场内图形的一部分，却吃掉一圈 exclusion。</p><footer>—— 对照 wafer edge exposure 模块的公开用途</footer></div><p><a href="/litho/track-defect-sources">上一课</a>点到边缘渣。缺口是有意的边缘曝光（WEE）：在扫描仪主曝光之外，把边缘环的正胶打到可溶。与 EBR 溶剂切珠分工：一个切厚珠，一个清薄残胶或定义边缘。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EBR 之后仍可能有薄胶裙，刻蚀时掉进腔体成颗粒。边缘芯片本就不完整，用光把胶去掉，换清洁。过宽 WEE 吃掉可出货管芯；过窄留渣。与 <a href="/litho/edge-field-partial">边缘场</a>（若已写）的剂量补偿不是同一旋钮。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>轨道或扫描仪附属模块：宽带或匹配胶敏感波长的灯，环形曝光。宽度与 EBR、notch 方位对齐。正胶：曝光+显影去掉；负胶逻辑相反，不要套用。须进入掩模与曝光场规划，避免 WEE 打到对准标记。</p>',7)),(a(),E(h,null,{default:r(()=>[n(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20EBR%5B%22EBR%20%E5%88%87%E7%8F%A0%22%5D%20--%3E%20WEE%5B%22%E8%BE%B9%E7%BC%98%E6%9B%9D%E5%85%89%22%5D%0A%20%20WEE%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%E5%8E%BB%E8%BE%B9%E8%83%B6%22%5D%0A%20%20DEV%20--%3E%20CLEAN%5B%22%E8%BE%B9%E7%BC%98%E6%B8%85%E6%B4%81%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p><span class="marginnote">有的厂把 WEE 放在主曝光前，有的后。相对 PEB 的次序改边缘 CD，须固定在配方里。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正胶边缘被打到剂量饱和，显影全溶。光学邻近在边缘终止，不需要 OPC 那一套——这里没有器件图形。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课背面与斜边：光够不着的地方，要溶剂或刷。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WEE 用光清边缘正胶，换腔体清洁，付 exclusion。</li><li>与 EBR、边缘场补偿分账。</li><li>出处：WEE 模块通识。</li></ul>',7))])}const P=i(p,[["render",c]]);export{T as __pageData,P as default};
